describe('Modal Close by Escape Key', () => {
  beforeEach(() => {
    cy.visit('/modal');
  });

  it('should close modal when Escape key is pressed', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal content is visible
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Press Escape key
    cy.get('[data-testid="body"]').type('{esc}');

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify modal close button is still visible
    cy.get('[data-testid="modal-close-btn"]').should('be.visible');

    // Verify page content is still visible
    cy.get('[data-testid="page-content"]').should('be.visible');
  });

  it('should not close modal when Escape key is pressed outside modal', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal content is visible
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Press Escape key outside modal
    cy.get('[data-testid="body"]').type('{esc}');

    // Verify modal is still open
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify page content is still visible
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Verify modal close button is still visible
    cy.get('[data-testid="modal-close-btn"]').should('be.visible');
  });
});
